/// <summary>
/// The MobPickOrderTypeProd class handles the production picking list data and posting logic.
/// </summary>
[TFMTableNameAttribute(tableStr(ProdJournalTable))]
class MobPickOrderTypeProd extends MobPickOrderType
{
    #mob
    ProdJournalTable journalTable;
    MobDocPickOrder  pickOrderDoc;

}

Method.Source:
    /// <summary>
    ///
    /// </summary>
    /// <param name = "_inventLocationID"></param>
    /// <param name = "_deliveryDate"></param>
    /// <param name = "_scannedValue"></param>
    /// <returns></returns>
    public Map getHeaderRecords(TFMRequestFiltersElement _filters, str _scannedValue)
    {
        InventLocation  inventLocation;
        Map             returnMap = new Map(Types::string, Types::Record);
        Common			ref = _filters.getReferredRecord();
		if ( ref.tableId == tableNum(MobPackingStation))
        {
            return returnMap;
        }

        inventLocation = MobHelper::getAllowedInventLocations(curUserId());
        while select inventLocation where (inventLocation.InventLocationId == _filters.parmWarehouse() || _filters.parmWarehouse() == MobConstants::all())
        {
            // Check if sales orders are enabled for this warehouse
            if (MobHelper::IsProdPickJournalEnabled(inventLocation.InventLocationId))
            {
                // Use the warehouse from the current iteration
                _filters.parmWarehouse(inventLocation.InventLocationId);
                returnMap = MobHelper::mergeMaps(returnMap,this.getProdPickJournals(_filters,_scannedValue));
                _filters.parmWarehouse(_filters.getFieldValue('warehouse'));
            }
        }

        return returnMap;
    }

public str getBackendID(Common _common)
{
    ProdJournalTable ProdJournalTable = _common;
    return tableStr(ProdJournalTable) + '/' + fieldStr(ProdJournalTable,JournalId) + '/' + prodJournalTable.JournalId;
}

